------------------------------NOTES-----------------------------------------------------------------------**/

/**---------------------------------------------------------------------------------------------------------------------------------**/
tw.local.latestContractNum = tw.local.ODCRequest.BasicDetails.flexCubeContractNo2 || tw.local.ODCRequest.BasicDetails.flexCubeContractNo || "";

tw.local.LiquidateBCCollectionReq = new tw.object.toolkit.NBEINTT.LiquidateBCCollectionReq();
tw.local.LiquidateBCCollectionReq.CONREFNO = tw.local.latestContractNum;
tw.local.LiquidateBCCollectionReq.LIQAMT = tw.local.ODCRequest.ContractLiquidation.liqAmount;
tw.local.LiquidateBCCollectionReq.VDATECR = tw.local.ODCRequest.ContractLiquidation.creditValueDate;
tw.local.LiquidateBCCollectionReq.DRVALDT = tw.local.ODCRequest.ContractLiquidation.debitValueDate;
tw.local.LiquidateBCCollectionReq.CUSTOMER_ID = tw.local.ODCRequest.cif;
tw.local.LiquidateBCCollectionReq.PRTYTYP = "DRAWER";
tw.local.LiquidateBCCollectionReq.BranchNumber = tw.local.ODCRequest.FinancialDetailsFO.executionHub.value;

/**---------------------------------------------Charges And Settlements-------------------------------------------------**/
tw.local.LiquidateBCCollectionReq.Charges = new tw.object.toolkit.NBEINTT.Charges_11();
tw.local.LiquidateBCCollectionReq.Charges.CONREFNO = tw.local.latestContractNum;

tw.local.LiquidateBCCollectionReq.Settlements = new tw.object.toolkit.NBEINTT.Settlements_16();
tw.local.LiquidateBCCollectionReq.Settlements.CONREFNO = tw.local.latestContractNum;
tw.local.LiquidateBCCollectionReq.Settlements.Contract_Settlement = new tw.object.listOf.toolkit.NBEINTT.Contract_Settlement_11();
/**----------------------------------------------Charges---------------------------------------------------------------**/
if (tw.local.ODCRequest.ChargesAndCommissions && tw.local.ODCRequest.ChargesAndCommissions.length > 0) {
	tw.local.LiquidateBCCollectionReq.Charges.Charge_Application = new tw.object.listOf.toolkit.NBEINTT.Charge_Application_8();

	for (var i = 0; i < tw.local.ODCRequest.ChargesAndCommissions.length; i++) {
		var component = tw.local.ODCRequest.ChargesAndCommissions[i].component;
		tw.local.LiquidateBCCollectionReq.Charges.Charge_Application[i] = new tw.object.toolkit.NBEINTT.Charge_Application_8();
		tw.local.LiquidateBCCollectionReq.Charges.Charge_Application[i].COMPNT = component;
		tw.local.LiquidateBCCollectionReq.Charges.Charge_Application[i].CHRGAMT = tw.local.ODCRequest.ChargesAndCommissions[i].changeAmount;
		tw.local.LiquidateBCCollectionReq.Charges.Charge_Application[i].WAIVER = tw.local.ODCRequest.ChargesAndCommissions[i].waiver ? "Y" : "N";

		//----------------------------------------------------------------------------------
		if (!tw.local.ODCRequest.ChargesAndCommissions[i].waiver && tw.local.ODCRequest.ChargesAndCommissions[i].debitedAccount) {
			var glAccountNo = tw.local.ODCRequest.ChargesAndCommissions[i].debitedAccount.glAccountNo;
			var accountNumber = tw.local.ODCRequest.ChargesAndCommissions[i].debitedAccount.customerAccountNo;
			var acc = glAccountNo || accountNumber;
			var accountBranchCode = tw.local.ODCRequest.ChargesAndCommissions[i].debitedAccount.branchCode;
			var accountCurrency = tw.local.ODCRequest.ChargesAndCommissions[i].debitedAccount.currency.value;
			addContractSettlement(component, accountBranchCode, acc, accountCurrency);
		}
	}
}

/**---------------------------------------------Contract Multitnr-------------------------------------------------**/
tw.local.LiquidateBCCollectionReq.Contract_Multitnr = new tw.object.listOf.toolkit.NBEINTT.Contract_Multitnr_4();
if (tw.local.ODCRequest.FinancialDetailsFO.multiTenorDates && tw.local.ODCRequest.FinancialDetailsFO.multiTenorDates.length > 0) {
	for (var i = 0; i < tw.local.ODCRequest.FinancialDetailsFO.multiTenorDates.length; i++) {
		tw.local.LiquidateBCCollectionReq.Contract_Multitnr[i] = new tw.object.toolkit.NBEINTT.Contract_Multitnr_4();
		tw.local.LiquidateBCCollectionReq.Contract_Multitnr[i].SERIALNUM = String(i-1);
		tw.local.LiquidateBCCollectionReq.Contract_Multitnr[i].BASDATE = formatDate(tw.local.ODCRequest.FinancialDetailsFO.multiTenorDates[i].instalmentBaseDate);
		tw.local.LiquidateBCCollectionReq.Contract_Multitnr[i].VALUDATE = formatDate(tw.local.ODCRequest.ContractCreation.valueDate);
		tw.local.LiquidateBCCollectionReq.Contract_Multitnr[i].LIQDTNAMT = String(tw.local.ODCRequest.FinancialDetailsFO.multiTenorDates[i].liquidationAmnt);
		tw.local.LiquidateBCCollectionReq.Contract_Multitnr[i].TNOR = String(tw.local.ODCRequest.FinancialDetailsFO.multiTenorDates[i].instalmentTenorDays);
		tw.local.LiquidateBCCollectionReq.Contract_Multitnr[i].MATDAT = formatDate(tw.local.ODCRequest.FinancialDetailsFO.multiTenorDates[i].instalmentMaturityDate);
		tw.local.LiquidateBCCollectionReq.Contract_Multitnr[i].BILLAMNT = String(tw.local.ODCRequest.FinancialDetailsFO.multiTenorDates[i].amount);
	}
}


/**---------------------------------------------Settlements-------------------------------------------------**/
var component = "BILL_LIQ_AMT";
var glAccountNo = tw.local.ODCRequest.ContractLiquidation.creditedAccount.glAccountNo || "";
var accountNumber = tw.local.ODCRequest.ContractLiquidation.creditedAccount.customerAccountNo || "";
var acc = glAccountNo || accountNumber;
var accountBranchCode = tw.local.ODCRequest.ContractLiquidation.creditedAccount.branchCode;
var accountCurrency = tw.local.ODCRequest.ContractLiquidation.creditedAccount.currency.value;

addContractSettlement(component, accountBranchCode, acc, accountCurrency);

/**----------------------------------------HELPER FUNCTIONS------------------------------------------------**/
function formatDate(date) {
	return date.format("yyyy-MM-dd");
}

// Function to add Contract Settlement
function addContractSettlement(component, accountBranchCode, accountNumber, accountCurrency) {
	var settlement = new tw.object.toolkit.NBEINTT.Contract_Settlement_11();
	settlement.COMPNT = component;
	settlement.ACCBRN = accountBranchCode;
	settlement.ACC = accountNumber;
	settlement.ACCCCY = accountCurrency;

	var len = tw.local.LiquidateBCCollectionReq.Settlements.Contract_Settlement.listLength;
	tw.local.LiquidateBCCollectionReq.Settlements.Contract_Settlement.insertIntoList(len, settlement);
}
